(function(){
const {R,pick,shuffle,sample,range,plural,gcd}=H;
const N=H.num,M=H.m,F=H.frac;
const ok=(c,msg)=>{if(!c)throw new Error('self-check failed: '+msg);};
function ch(right,wrong){const w=[];wrong.forEach(x=>{x=String(x);if(x!==String(right)&&!w.includes(x))w.push(x);});
 const o=shuffle([String(right),...w.slice(0,3)].map((s,i)=>({s,i})));return {opts:o.map(x=>x.s),ans:o.findIndex(x=>x.i===0)};}
const fr=(n,d)=>{if(d<0){n=-n;d=-d;}const g=gcd(n,d)||1;return [n/g,d/g];};
const FH=(n,d)=>{[n,d]=fr(n,d);return d===1?N(n):(n<0?'−':'')+F(Math.abs(n),d);};
const FT=(n,d)=>{[n,d]=fr(n,d);return d===1?String(n):n+'/'+d;};
/* fraction answer */
const FA=(n,d)=>({ans:n/d,ansText:FH(n,d),ph:'например, 3/8',keys:['/']});
/* rounded answer (to hundredths) */
const r2=x=>Math.round(x*100)/100;
const RA=v=>({ans:v,check:raw=>{const x=H.parseNum(raw);return Math.abs(x-v)<=0.0051;},right:N(r2(v)),ansText:`≈ ${N(r2(v))}`,ph:'до сотых, например 0,79',keys:[',']});
const near=(a,b,e)=>Math.abs(a-b)<(e||0.01);
/* numeric area of {(x,y) in [0,W]x[0,H] : f} by midpoint grid */
function gridP(f,W,Hh,n){n=n||220;let c=0;for(let i=0;i<n;i++)for(let j=0;j<n;j++)if(f((i+0.5)*W/n,(j+0.5)*Hh/n))c++;return c/(n*n);}
/* theory helpers */
const CHK=(q,a)=>`<div class="box ex"><b>🔎 Проверь себя</b>${q}<details style="margin-top:6px"><summary style="cursor:pointer;color:var(--accent-ink);font-weight:600">Показать ответ</summary><div style="margin-top:6px">${a}</div></details></div>`;
const MEM=t=>`<div class="box tip"><b>📌 Запомни</b>${t}</div>`;
const EX=(title,task,steps,ans)=>`<div class="box ex"><b>${title}</b>${task}${steps.map((s,i)=>`<div style="margin:5px 0"><b>Шаг ${i+1}.</b> ${s}</div>`).join('')}${ans?`<div style="margin-top:4px">✅ <b>${ans}</b></div>`:''}</div>`;
const FIG=(svg,cap)=>`<div class="figrow"><div class="fig">${svg}${cap?`<div class="cap">${cap}</div>`:''}</div></div>`;
const SV=(W,Hh,lab)=>`<svg viewBox="0 0 ${W} ${Hh}" width="${W}" role="img" aria-label="${lab||'Рисунок'}" style="font-family:system-ui,sans-serif">`;

/* ---------- SVG: segment ---------- */
function segSVG(a,b,parts,o){o=o||{};const W=320,Hh=62;const X=x=>20+(x-a)/(b-a)*(W-40);const Y=30;
 let s=SV(W,Hh,'Отрезок');
 s+=`<line x1="${X(a)}" y1="${Y}" x2="${X(b)}" y2="${Y}" stroke="var(--fig)" stroke-width="3"/>`;
 parts.forEach(([c,d])=>{s+=`<line x1="${X(c)}" y1="${Y}" x2="${X(d)}" y2="${Y}" stroke="var(--hl)" stroke-width="9" stroke-opacity="0.75" stroke-linecap="butt"/>`;});
 const marks=new Set([a,b]);parts.forEach(([c,d])=>{marks.add(c);marks.add(d);});(o.marks||[]).forEach(m=>marks.add(m));
 const ms=[...marks].sort((p,q)=>p-q);let last=-99,row=0;
 ms.forEach(m=>{const px=X(m);row=(px-last<26&&row===0)?1:0;last=px;s+=`<line x1="${px}" y1="${Y-7}" x2="${px}" y2="${Y+7}" stroke="var(--fig)" stroke-width="1.6"/><text x="${px}" y="${Y+22+row*13}" text-anchor="middle" font-size="12" fill="var(--accent-ink)" font-weight="700">${N(m)}</text>`;});
 if(o.A)s+=`<text x="${X(a)}" y="${Y-12}" text-anchor="middle" font-size="13" font-weight="700" fill="var(--ink)">${o.A}</text><text x="${X(b)}" y="${Y-12}" text-anchor="middle" font-size="13" font-weight="700" fill="var(--ink)">${o.B}</text>`;
 return s+'</svg>';}
/* ---------- SVG: plane box [0,w]x[0,h] ---------- */
function plane(w,h,draw,o){o=o||{};const size=o.size||200,pad=o.pad==null?26:o.pad;const S=size/Math.max(w,h);const W=w*S+2*pad,Hh=h*S+2*pad;const X=x=>+(pad+x*S).toFixed(1),Y=y=>+(Hh-pad-y*S).toFixed(1);
 const P=pts=>pts.map(([x,y])=>X(x)+','+Y(y)).join(' ');
 let s=SV(W,Hh,o.lab);
 s+=draw({X,Y,S,P,W,Hh});
 return s+'</svg>';}
const HL='fill="var(--hl)" fill-opacity="0.55"';
function rectOut(g,w,h){return `<rect x="${g.X(0)}" y="${g.Y(h)}" width="${w*g.S}" height="${h*g.S}" fill="none" stroke="var(--fig)" stroke-width="2"/>`;}
/* unit square for two numbers / meeting */
function sqSVG(T,polys,o){o=o||{};return plane(T,T,g=>{let s='';polys.forEach(p=>{s+=`<polygon points="${g.P(p)}" ${HL} stroke="var(--accent-ink)" stroke-width="1.2"/>`;});
 s+=rectOut(g,T,T);
 s+=`<text x="${g.X(0)-6}" y="${g.Y(0)+15}" font-size="12" fill="var(--ink)" text-anchor="end">0</text><text x="${g.X(T)}" y="${g.Y(0)+16}" font-size="12" fill="var(--ink)" text-anchor="middle">${o.tl||N(T)}</text><text x="${g.X(0)-6}" y="${g.Y(T)+4}" font-size="12" fill="var(--ink)" text-anchor="end">${o.tl||N(T)}</text>`;
 s+=`<text x="${g.X(T/2)}" y="${g.Y(0)+18}" font-size="13" font-style="italic" fill="var(--accent-ink)" text-anchor="middle">${o.xl||'x'} →</text><text x="${g.X(0)+4}" y="${g.Y(T)-8}" font-size="13" font-style="italic" fill="var(--accent-ink)" text-anchor="start">↑ ${o.yl||'y'}</text>`;
 if(o.diag)s+=`<line x1="${g.X(0)}" y1="${g.Y(0)}" x2="${g.X(T)}" y2="${g.Y(T)}" stroke="var(--fig)" stroke-dasharray="4 3"/>`;
 return s;},{size:o.size||190,pad:30,lab:o.lab});}
function meetPoly(T,a,b){return [[0,0],[b,0],[T,T-b],[T,T],[T-a,T],[0,a]];}
/* x+y<=s region in [0,1]^2 */
function sumPoly(s){return s<=1?[[0,0],[s,0],[0,s]]:[[0,0],[1,0],[1,s-1],[s-1,1],[0,1]];}
/* target */
function targetSVG(rs,hl){const Rm=rs[rs.length-1],S=120/Rm,c=135;let s=SV(270,270,'Мишень');
 for(let i=rs.length-1;i>=0;i--){const on=hl===i;s+=`<circle cx="${c}" cy="${c}" r="${rs[i]*S}" fill="${on?'var(--hl)':'var(--card)'}" ${on?'fill-opacity="0.6"':''} stroke="var(--fig)" stroke-width="1.6"/>`;}
 if(hl!=null&&hl>0)s+=`<circle cx="${c}" cy="${c}" r="${rs[hl-1]*S}" fill="var(--card)" stroke="var(--fig)" stroke-width="1.6"/>`;
 if(hl!=null&&hl>1)for(let i=hl-2;i>=0;i--)s+=`<circle cx="${c}" cy="${c}" r="${rs[i]*S}" fill="var(--card)" stroke="var(--fig)" stroke-width="1.6"/>`;
 rs.forEach((r,i)=>{s+=`<text x="${c+r*S-(i===0?r*S/2:(r-rs[i-1])*S/2)}" y="${c-4}" text-anchor="middle" font-size="11" font-weight="700" fill="var(--accent-ink)">${N(r)}</text>`;});
 s+=`<circle cx="${c}" cy="${c}" r="2" fill="var(--fig)"/><line x1="${c}" y1="${c}" x2="${c+Rm*S}" y2="${c}" stroke="var(--fig)" stroke-width="1" stroke-dasharray="3 2"/>`;
 return s+'</svg>';}
/* circle in square */
function circInSq(){return plane(2,2,g=>`<rect x="${g.X(0)}" y="${g.Y(2)}" width="${2*g.S}" height="${2*g.S}" fill="var(--card)" stroke="var(--fig)" stroke-width="2"/><circle cx="${g.X(1)}" cy="${g.Y(1)}" r="${g.S}" ${HL} stroke="var(--accent-ink)" stroke-width="1.5"/><line x1="${g.X(1)}" y1="${g.Y(1)}" x2="${g.X(2)}" y2="${g.Y(1)}" stroke="var(--fig)" stroke-dasharray="3 2"/><text x="${g.X(1.5)}" y="${g.Y(1)-5}" font-size="13" text-anchor="middle" fill="var(--ink)">r</text><text x="${g.X(1)}" y="${g.Y(0)+18}" font-size="13" text-anchor="middle" fill="var(--ink)">2r</text>`,{size:150,pad:24,lab:'Круг в квадрате'});}
/* cells picture */
function cellsSVG(n,on){return plane(n,n,g=>{let s='';on.forEach(([i,j])=>{s+=`<rect x="${g.X(i)}" y="${g.Y(j+1)}" width="${g.S}" height="${g.S}" ${HL}/>`;});for(let i=0;i<=n;i++){s+=`<line x1="${g.X(i)}" y1="${g.Y(0)}" x2="${g.X(i)}" y2="${g.Y(n)}" stroke="var(--fig)" stroke-width="${i%n?0.8:2}"/><line x1="${g.X(0)}" y1="${g.Y(i)}" x2="${g.X(n)}" y2="${g.Y(i)}" stroke="var(--fig)" stroke-width="${i%n?0.8:2}"/>`;}return s;},{size:180,pad:10,lab:'Клетчатый квадрат'});}
/* stick */
function stickSVG(L,cuts,o){o=o||{};const W=320,X=x=>20+x/L*(W-40);let s=SV(W,54,'Палка');const pts=[0,...cuts,L];
 for(let i=0;i<pts.length-1;i++)s+=`<rect x="${X(pts[i])+1}" y="14" width="${Math.max(1,X(pts[i+1])-X(pts[i])-2)}" height="12" rx="3" fill="${i%2?'var(--accent)':'var(--hl)'}" fill-opacity="0.7"/>`;
 cuts.forEach(c=>{s+=`<line x1="${X(c)}" y1="8" x2="${X(c)}" y2="32" stroke="var(--bad)" stroke-width="2"/>`;});
 if(o.lab)for(let i=0;i<pts.length-1;i++)s+=`<text x="${(X(pts[i])+X(pts[i+1]))/2}" y="46" text-anchor="middle" font-size="12" fill="var(--ink)">${o.lab[i]}</text>`;
 return s+'</svg>';}

/* ---------- theory ---------- */
const theory=[
{title:'Что такое геометрическая вероятность',lvl:0,html:`
<p class="hook">Ты прибегаешь на остановку в случайный момент. Автобус ходит ровно раз в 10 минут. Какова вероятность, что ждать придётся меньше 3 минут? Исходов тут бесконечно много — момент времени может быть любым. Посчитать «хорошие исходы» штуками не получится. Но ответ есть, и он очень простой: <b>3/10</b>. Сейчас поймёшь почему.</p>
<p><b>Как другу.</b> Раньше вероятность считали так: хорошие исходы делить на все исходы. Например, кубик: 1 хороший из 6.</p>
<p>Но точек на отрезке бесконечно много. Их не пересчитать.</p>
<p>Поэтому вместо «количества» берём <b>размер</b>: длину, площадь или время.</p>
<p>Представь, что точку бросают вслепую, и она с равным шансом может оказаться где угодно. Тогда шанс попасть в кусок равен тому, <b>какую долю</b> всей фигуры этот кусок занимает.</p>
<div class="box rule"><b>Геометрическая вероятность</b>Если точка выбирается <b>случайно и равномерно</b> в фигуре Ω, то вероятность попасть в часть A:<br><b>P(A) = ${F('мера A','мера Ω')}</b>, где «мера» — это <b>длина</b> (на отрезке), <b>площадь</b> (в фигуре) или <b>время</b> (на промежутке времени).</div>
<p><b>Почему так?</b> «Равномерно» значит: одинаковые по размеру кусочки получают одинаковый шанс. Если кусок занимает 3/10 отрезка, в него «влезает» 3/10 всех шансов.</p>
${FIG(segSVG(0,10,[[0,3]]),'Ждём меньше 3 минут: 3 из 10 минут — P = 3/10')}
${EX('Пример 1 (легко)','Точку случайно выбирают на отрезке [0; 10]. Какова вероятность, что она окажется левее 3?',['Весь отрезок имеет длину 10.','Хорошая часть — от 0 до 3, её длина 3.','P = 3 : 10 = 0,3.'],'P = 0,3')}
${EX('Пример 2 (средне)','Внутри квадрата 4 × 4 нарисован квадрат 2 × 2. Точку бросают в большой квадрат. Какова вероятность попасть в маленький?',['Мера здесь — площадь. Площадь большого: 4 · 4 = 16.','Площадь маленького: 2 · 2 = 4.',`P = ${F(4,16)} = ${F(1,4)}. Обрати внимание: сторона меньше в 2 раза, а вероятность — в 4!`],'P = 1/4')}
${EX('Пример 3 (сложнее)','Автобус ходит каждые 10 минут. Какова вероятность ждать <b>больше</b> 7 минут?',['Момент прихода — случайная точка на отрезке времени длиной 10 минут (между двумя автобусами).','Ждать больше 7 минут — значит прийти в первые 3 минуты после ушедшего автобуса. Длина хорошей части: 10 − 7 = 3.','P = 3/10 = 0,3.'],'P = 0,3')}
<div class="box err"><b>Ловушка</b>Вероятность попасть в <b>одну конкретную точку</b> равна 0 — у точки нет длины. Поэтому неважно, включаем ли мы концы отрезка: P(x ≤ 3) = P(x < 3).</div>
<div class="fact">Вероятность 0 не значит «невозможно». Точка ведь куда-то попала, хотя шанс попасть именно туда был 0. Математики говорят: «почти никогда».</div>
${CHK('Точку выбирают на отрезке [0; 20]. Какова вероятность, что она попадёт на отрезок [5; 9]?','Длина хорошей части 9 − 5 = 4, вся длина 20: P = 4/20 = <b>1/5</b>.')}
${MEM(`<b>P = хорошая часть : вся фигура</b> (длина, площадь или время).<br>Трюк: представь, что фигуру равномерно «заливает дождём». Доля капель на куске = доля площади куска.`)}`},
{title:'Точка на отрезке',lvl:1,html:`
<p><b>Как другу.</b> В игре персонаж телепортируется в случайную точку моста длиной 100 м. Шанс оказаться на первых 20 метрах — 20/100.</p>
<p>Главное — понять, <b>какие точки «хорошие»</b>, и найти их общую длину.</p>
<div class="box rule"><b>Правило</b>Точку случайно выбирают на отрезке длиной L. Если хорошие точки образуют кусок (или несколько кусков) общей длиной ℓ, то <b>P = ℓ / L</b>.</div>
<p><b>Совет:</b> всегда рисуй отрезок и закрашивай хорошую часть. Так ты точно не ошибёшься.</p>
${EX('Пример 1 (легко)','Точку C выбирают на отрезке AB. Какова вероятность, что C ближе к A, чем к B?',['Ближе к A — значит левее середины отрезка.','Хорошая часть — левая половина. Её длина L/2.','P = (L/2) : L = 1/2.'],'P = 1/2')}
${EX('Пример 2 (средне)','Палку длиной 10 см ломают в случайной точке. Какова вероятность, что <b>оба</b> куска будут длиннее 2 см?',['Пусть x — расстояние от левого конца до излома. Левый кусок x, правый 10 − x.','Нужно x > 2 и 10 − x > 2, то есть 2 < x < 8.','Хорошая длина 8 − 2 = 6. P = 6/10 = 0,6.'],'P = 0,6')}
${FIG(segSVG(0,10,[[2,8]]),'Излом в закрашенной части — оба куска длиннее 2 см')}
${EX('Пример 3 (сложнее)','Число x выбирают случайно на отрезке [−3; 5]. Какова вероятность, что x² < 4?',['Решим неравенство: x² < 4 ⇔ −2 < x < 2.','Это кусок длиной 4. Он целиком внутри [−3; 5].','Длина всего отрезка 5 − (−3) = 8. P = 4/8 = 1/2.'],'P = 1/2')}
<div class="box err"><b>Частая ошибка</b>Делить на «правую границу», а не на длину: для [−3; 5] длина — 8, а не 5. Длина = правый конец − левый конец.</div>
${CHK('Точку выбирают на отрезке [0; 12]. Какова вероятность, что расстояние от неё до ближайшего конца меньше 3?','Хорошие части: [0; 3) и (9; 12]. Общая длина 6, P = 6/12 = <b>1/2</b>.')}
${CHK('Палку длиной 1 м ломают в случайной точке. Какова вероятность, что меньший кусок короче 10 см?','Излом в первых 10 см или в последних 10 см: 20 см из 100. P = <b>0,2</b>.')}
${MEM(`Нарисуй отрезок → закрась хорошие точки → <b>длина закрашенного : длина всего</b>.`)}`},
{title:'Точка в фигуре: отношение площадей',lvl:2,html:`
<p><b>Как другу.</b> Капля дождя падает на квадратную плитку, на которой нарисован круг. Куда именно — случайно. Шанс попасть в круг = доля площади, которую занимает круг.</p>
<div class="box rule"><b>Правило</b>Точку случайно бросают в фигуру Ω. Вероятность попасть в часть A:<br><b>P = S(A) / S(Ω)</b>.</div>
<p><b>Нужные площади:</b> прямоугольник a · b, треугольник ½ · основание · высоту, круг πr², четверть круга ¼πr².</p>
${FIG(circInSq(),'Круг, вписанный в квадрат: P = πr² : (2r)² = π/4 ≈ 0,79')}
${EX('Пример 1 (легко)','В квадрате 5 × 5 клеток закрашено 7 клеток. Точку бросают в квадрат. Какова вероятность попасть в закрашенную клетку?',['Площадь квадрата — 25 клеток.','Закрашено 7 клеток.','P = 7/25 = 0,28.'],'P = 0,28')}
${EX('Пример 2 (средне)','В квадрат вписан круг. Точку бросают в квадрат. Какова вероятность попасть в круг?',['Пусть радиус r. Тогда сторона квадрата 2r, его площадь (2r)² = 4r².','Площадь круга πr².',`P = ${F('πr²','4r²')} = ${F('π',4)} ≈ 0,785. Радиус сократился — ответ не зависит от размера!`],'P = π/4 ≈ 0,79')}
${EX('Пример 3 (сложнее)','Точку бросают в квадрат ABCD со стороной 2. Какова вероятность, что она окажется ближе 1 к вершине A?',['Точки на расстоянии меньше 1 от A — это круг радиуса 1 с центром A.','Внутри квадрата помещается только четверть этого круга: площадь ¼ · π · 1² = π/4.','Площадь квадрата 4. P = (π/4) : 4 = π/16 ≈ 0,20.'],'P = π/16 ≈ 0,20')}
<div class="widget" id="w-dart"></div>
<div class="box err"><b>Ловушка</b>Делить <b>длины</b>, а не площади. Если сторона маленького квадрата в 2 раза меньше, вероятность попасть в него не 1/2, а <b>1/4</b>.</div>
<div class="fact">Так можно «измерить» число π, просто бросая точки! Это называется методом Монте-Карло — в честь казино в Монако. Его придумали физики в 1940-х для расчётов, которые не решались формулами.</div>
${CHK('Внутри прямоугольника 6 × 4 нарисован треугольник с основанием 6 (нижняя сторона) и вершиной на верхней стороне. Какова вероятность попасть в треугольник?','S треугольника = ½ · 6 · 4 = 12, S прямоугольника = 24. P = <b>1/2</b> — где бы ни была вершина!')}
${MEM(`<b>P = S(хорошая часть) : S(вся фигура)</b>.<br>Трюк: размеры «в k раз меньше» → площадь в <b>k²</b> раз меньше.`)}`},
{title:'Мишень и дартс',lvl:3,html:`
<p><b>Как другу.</b> Мишень — это круги один в другом. Если дротик попадает в мишень <b>случайно</b> (кидаешь, не целясь), то шанс попасть в «яблочко» — это доля его площади.</p>
<p>А площадь круга зависит от <b>квадрата</b> радиуса. Поэтому радиус вдвое меньше — площадь вчетверо меньше.</p>
<div class="box rule"><b>Правило</b>Мишень радиуса R. Вероятность попасть:<br>• в круг радиуса r: <b>P = ${F('πr²','πR²')} = ${F('r²','R²')}</b>;<br>• в кольцо между r₁ и r₂: <b>P = ${F('r₂² − r₁²','R²')}</b>.<br>π сокращается!</div>
${FIG(targetSVG([1,2,3],1),'Мишень с радиусами 1, 2, 3; выделено среднее кольцо')}
${EX('Пример 1 (легко)','Мишень радиуса 3, «яблочко» радиуса 1. Какова вероятность попасть в «яблочко»?',['Площадь яблочка π · 1² = π, всей мишени π · 3² = 9π.','P = π : 9π = 1/9.'],'P = 1/9')}
${EX('Пример 2 (средне)','Та же мишень (радиусы 1, 2, 3). Какова вероятность попасть в среднее кольцо?',['Кольцо = круг радиуса 2 минус круг радиуса 1: площадь 4π − π = 3π.','Вся мишень 9π.','P = 3π : 9π = 1/3.'],'P = 1/3')}
${EX('Пример 3 (сложнее)','Мишень из 5 колец одинаковой ширины. Какова вероятность попасть во внешнее кольцо?',['Пусть ширина кольца 1. Радиусы: 1, 2, 3, 4, 5.','Внешнее кольцо: 5² − 4² = 25 − 16 = 9 (в «π-единицах»).','Вся мишень 5² = 25. P = 9/25 = 0,36. Внешнее кольцо — самое «жирное»!'],'P = 9/25')}
<div class="box err"><b>Частая ошибка</b>Считать по радиусам: «радиус 1 из 3 — значит 1/3». Нет! Нужны <b>квадраты</b> радиусов: 1/9.</div>
<div class="fact">В настоящем дартсе игроки целятся, поэтому для них геометрическая вероятность не подходит. А вот для «слепого» броска или капли дождя — подходит идеально.</div>
${CHK('Мишень радиуса 10, яблочко радиуса 2. Какова вероятность попасть в яблочко?','2² : 10² = 4/100 = <b>1/25</b>.')}
${MEM(`Круг: <b>(r/R)²</b>. Кольцо: <b>(r₂² − r₁²)/R²</b>.<br>Трюк: «радиус в квадрате» — у площади всегда квадрат.`)}`},
{title:'Случайный момент времени',lvl:4,html:`
<p><b>Как другу.</b> Время — это тоже отрезок! От 12:00 до 13:00 — отрезок длиной 60 минут. Если ты приходишь «в случайный момент», это случайная точка на этом отрезке.</p>
<div class="box rule"><b>Правило</b>Если момент выбирается случайно и равномерно на промежутке длиной T, то вероятность попасть в «хорошие» промежутки общей длиной t:<br><b>P = t / T</b>.</div>
${EX('Пример 1 (легко)','Автобус ходит каждые 12 минут. Какова вероятность ждать не больше 4 минут?',['Между двумя автобусами — отрезок 12 минут. Ты приходишь в случайную точку.','Ждёшь не больше 4 минут, если пришёл в последние 4 минуты перед автобусом.','P = 4/12 = 1/3.'],'P = 1/3')}
${EX('Пример 2 (средне)','Светофор: зелёный 40 с, жёлтый 5 с, красный 35 с, потом всё повторяется. Какова вероятность подъехать на красный?',['Полный цикл: 40 + 5 + 35 = 80 секунд.','Красный — 35 секунд из них.','P = 35/80 = 7/16.'],'P = 7/16')}
${EX('Пример 3 (сложнее)','Урок 45 минут. Уведомление на телефон приходит в случайный момент урока. Какова вероятность, что оно придёт в первые 10 или в последние 5 минут?',['Хорошие куски: первые 10 минут и последние 5 минут.','Они не пересекаются, поэтому складываем: 10 + 5 = 15.','P = 15/45 = 1/3.'],'P = 1/3')}
<div class="box err"><b>Ловушка</b>«Ждать больше t» и «ждать не больше t» — противоположные события. Их вероятности в сумме дают 1. Проверяй себя этим!</div>
${CHK('Поезд метро ходит каждые 3 минуты. Какова вероятность ждать больше 1 минуты?','Хорошие моменты — первые 2 минуты после ушедшего поезда: P = <b>2/3</b>.')}
${MEM(`Время — это отрезок. <b>P = хорошее время : весь цикл</b>.`)}`},
{title:'Задача о встрече',lvl:5,html:`
<p class="hook">Ты и друг договорились встретиться у фонтана между 12:00 и 13:00. Каждый приходит в случайный момент и ждёт другого 15 минут, потом уходит. Каков шанс встретиться? Интуиция говорит «четверть». А правильный ответ почти вдвое больше!</p>
<p><b>Как другу.</b> Здесь случайных чисел <b>два</b>: время прихода тебя (x) и друга (y). Пара (x; y) — это <b>точка в квадрате</b> 60 × 60.</p>
<p>Вы встречаетесь, если пришли с разницей не больше 15 минут: |x − y| ≤ 15.</p>
<p>На рисунке это <b>полоса вдоль диагонали</b>. Осталось найти её площадь.</p>
<div class="box rule"><b>Метод квадрата</b>1) Отложи время прихода одного по оси x, другого — по оси y. Все исходы — квадрат T × T.<br>2) Встреча ⇔ |x − y| ≤ t — полоса вдоль диагонали.<br>3) Проще найти площадь двух <b>угловых треугольников</b> (там встречи нет): каждый с катетами T − t.<br>4) <b>P = 1 − ${F('(T − t)²','T²')}</b>.</div>
${FIG(sqSVG(60,[meetPoly(60,15,15)],{tl:'60',xl:'ты',yl:'друг',diag:true}),'Полоса |x − y| ≤ 15 — здесь вы встретились')}
${EX('Пример 1 (средне)','T = 60 минут, каждый ждёт 15 минут. Найди вероятность встречи.',['Все исходы — квадрат 60 × 60, площадь 3 600.','Нет встречи — два треугольника с катетами 60 − 15 = 45. Вместе они составляют квадрат 45 × 45 = 2 025.','Площадь полосы: 3 600 − 2 025 = 1 575.',`P = ${F('1 575','3 600')} = ${F(7,16)} ≈ 0,44.`],'P = 7/16')}
${EX('Пример 2 (проще, через доли)','T = 60, ждут по 30 минут.',['Катеты треугольников: 60 − 30 = 30, это половина стороны.',`Два треугольника вместе — квадрат со стороной в 2 раза меньше: его доля (${F(1,2)})² = ${F(1,4)}.`,`P = 1 − ${F(1,4)} = ${F(3,4)}.`],'P = 3/4')}
${EX('Пример 3 (сложнее)','Ты ждёшь 20 минут, а друг — только 10 (T = 60).',['Если ты пришёл раньше (x < y), встреча, когда y − x ≤ 20. Если друг раньше — когда x − y ≤ 10.','Треугольники «без встречи» теперь разные: с катетами 40 и 50.',`Их площади: ½ · 40² = 800 и ½ · 50² = 1 250. P = 1 − ${F('800 + 1 250','3 600')} = 1 − ${F(41,72)} = ${F(31,72)}.`],'P = 31/72')}
<div class="widget" id="w-meet"></div>
<div class="box err"><b>Ловушка</b>Думать «ждём 15 минут из 60 → 1/4». Это неверно: встреча зависит от <b>разницы</b> двух случайных моментов, а это уже двумерная задача.</div>
${CHK('T = 60, каждый ждёт 20 минут. Найди P.',`1 − (40/60)² = 1 − 4/9 = <b>5/9</b>.`)}
${MEM(`Два случайных момента → <b>точка в квадрате</b>. Встреча → полоса у диагонали. <b>P = 1 − ((T − t)/T)²</b>.`)}`},
{title:'Два случайных числа',lvl:6,html:`
<p><b>Как другу.</b> Компьютер выбирает два случайных числа x и y от 0 до 1. Пара (x; y) — точка в единичном квадрате. Площадь квадрата 1, поэтому <b>вероятность = просто площадь</b> хорошей части!</p>
<div class="box rule"><b>Правило</b>x, y — случайные числа из [0; 1]. Точка (x; y) равномерно распределена в квадрате 1 × 1.<br><b>P(условие) = площадь части квадрата, где условие выполнено</b>.</div>
<p><b>Как найти часть:</b> замени «<» на «=», нарисуй прямую, потом проверь одну точку (например, (0; 0)) — с какой стороны условие выполнено.</p>
${FIG(sqSVG(1,[sumPoly(1)],{tl:'1'}),'x + y < 1: треугольник под прямой x + y = 1, площадь 1/2')}
${EX('Пример 1 (легко)','Какова вероятность, что x + y < 1?',['Прямая x + y = 1 проходит через (1; 0) и (0; 1).','Точка (0; 0): 0 + 0 < 1 — верно. Значит, нужна часть <b>под</b> прямой — прямоугольный треугольник с катетами 1.','Площадь ½ · 1 · 1 = ½.'],'P = 1/2')}
${EX('Пример 2 (средне)','Какова вероятность, что x + y < ½?',['Прямая x + y = ½ отсекает треугольник с катетами ½.',`Площадь ½ · ½ · ½ = ${F(1,8)}.`],'P = 1/8')}
${EX('Пример 3 (сложнее)','Какова вероятность, что числа отличаются меньше чем на 0,5: |x − y| < 0,5?',['Это та же «полоса встречи» вдоль диагонали!','Вне полосы — два угловых треугольника с катетами 1 − 0,5 = 0,5. Вместе — квадрат 0,5 × 0,5 = 0,25.','P = 1 − 0,25 = 0,75.'],'P = 3/4')}
<div class="box err"><b>Частая ошибка</b>Для x + y < 1,5 треугольник «выходит» за квадрат. Тогда проще посчитать то, что <b>не</b> подходит: угол x + y > 1,5 — треугольник с катетами 0,5, площадь 1/8. P = 1 − 1/8 = 7/8.</div>
${CHK('x, y — случайные числа из [0; 1]. Какова вероятность, что y > x?','Половина квадрата над диагональю: <b>1/2</b>.')}
${CHK('Какова вероятность, что оба числа больше 0,6?','Квадратик 0,4 × 0,4 в правом верхнем углу: <b>0,16</b>.')}
${MEM(`Два числа из [0; 1] → <b>точка в квадрате 1 × 1</b>, вероятность = <b>площадь</b>.<br>Трюк: замени знак на «=», нарисуй прямую, проверь точку (0; 0).`)}`},
{title:'★ Сломанная палка, монета на плитке, игла Бюффона',lvl:[7,8],html:`
<p class="hook">Палку ломают в двух случайных местах. Можно ли сложить из трёх кусков треугольник? Иногда да, иногда нет. А как часто? Ответ — ровно <b>1/4</b>, и его можно увидеть на картинке.</p>
<p><b>Как другу.</b> Треугольник из кусков a, b, c получается, только если каждый кусок <b>меньше половины</b> палки. Иначе самый длинный кусок не дотянется — две другие стороны слишком короткие (неравенство треугольника).</p>
<div class="box rule"><b>Сломанная палка</b>Палку длиной 1 ломают в двух случайных точках x и y. Из кусков можно сложить треугольник ⇔ каждый кусок < ½.<br>Ответ: <b>P = 1/4</b>.</div>
${EX('Почему 1/4 (шаг за шагом)','Палка [0; 1], изломы в точках x и y.',['Пара (x; y) — точка в квадрате 1 × 1. Пусть сначала x < y (нижний треугольник квадрата, площадь ½).','Куски: x, y − x, 1 − y. Все < ½: x < ½, y > ½, y − x < ½.','Это маленький треугольник с вершинами (0; ½), (½; ½), (½; 1) — площадь ½ · ½ · ½ = ⅛.','Для y < x картинка симметрична — ещё ⅛. Итого ⅛ + ⅛ = ¼.'],'P = 1/4')}
${FIG(sqSVG(1,[[[0,0.5],[0.5,0.5],[0.5,1]],[[0.5,0],[0.5,0.5],[1,0.5]]],{tl:'1',diag:true}),'Два треугольника по 1/8 — треугольник складывается')}
<div class="widget" id="w-stick"></div>
<div class="box rule"><b>Монета на плитке (задача типа Бюффона)</b>Пол выложен квадратной плиткой со стороной a. Монету диаметра d < a бросают случайно. Монета не задевает швов ⇔ её <b>центр</b> попал во внутренний квадрат со стороной a − d.<br><b>P(не задела) = (a − d)² / a²</b>.</div>
${EX('Пример (сложнее)','Плитка 10 см, монета диаметром 2 см. Какова вероятность, что монета ляжет целиком на одну плитку?',['Следим только за центром монеты. Он должен быть дальше 1 см (радиус) от каждого шва.','Это квадрат со стороной 10 − 2 = 8 см внутри плитки.','P = 8² : 10² = 64/100 = 0,64.'],'P = 0,64')}
<div class="fact">В 1777 году граф Бюффон бросал иглу на пол из досок и посчитал: если длина иглы равна половине ширины доски, она пересекает щель с вероятностью 1/π. Так, бросая иглу тысячи раз, можно приближённо найти π!</div>
${CHK('Пол из длинных досок шириной 6 см. Монета диаметром 2 см. Какова вероятность, что монета не заденет щель между досками?','Центр должен быть в полосе шириной 6 − 2 = 4 из 6: P = <b>2/3</b>.')}
${MEM(`Палка → треугольник: <b>1/4</b>. Монета → следи за <b>центром</b>, «сжимай» плитку на диаметр.`)}`},
{title:'Шпаргалка',html:`
<ol class="steps">
<li>Отрезок: P = <b>длина хорошей части : длина всего</b>.</li>
<li>Фигура: P = <b>площадь хорошей части : площадь всего</b>.</li>
<li>Время: P = <b>хорошее время : весь цикл</b>.</li>
<li>Круги: P = (r/R)². Кольцо: (r₂² − r₁²)/R².</li>
<li>Два случайных момента или числа → <b>точка в квадрате</b>.</li>
<li>Встреча: P = 1 − ((T − t)/T)².</li>
<li>Сломанная палка → треугольник: 1/4.</li>
<li>P одной точки = 0; концы отрезков не важны.</li></ol>`}
];

/* ---------- symbols ---------- */
const symbols={tab:'Формулы',title:'Формулы геометрической вероятности',rows:[
['P = ℓ / L','на отрезке','Длина хорошей части делить на длину всего отрезка.','[2; 5] на [0; 10]: 3/10'],
['P = S(A) / S(Ω)','в фигуре','Площадь хорошей части делить на площадь фигуры.','круг в квадрате: π/4'],
['P = t / T','во времени','Хорошее время делить на длину цикла.','автобус раз в 10 мин, ждать ≤ 3: 3/10'],
['(r / R)²','мишень','Вероятность попасть в круг радиуса r внутри мишени радиуса R.','r = 1, R = 3: 1/9'],
['(r₂² − r₁²) / R²','кольцо','Вероятность попасть в кольцо.','1 < ρ < 2 при R = 3: 1/3'],
['1 − ((T − t)/T)²','задача о встрече','Двое ждут по t минут в промежутке T.','T = 60, t = 15: 7/16'],
['(x; y) ∈ [0; 1]²','два числа','Пара случайных чисел — точка в квадрате, P = площадь.','x + y < 1: 1/2'],
['πr²','площадь круга','Нужна для мишеней и кругов в квадрате.','r = 2: 4π'],
['(a − d)² / a²','монета на плитке','Монета диаметра d целиком на плитке со стороной a.','a = 10, d = 2: 0,64'],
['1/4','сломанная палка','Шанс сложить треугольник из трёх кусков.','']
],after:`<div class="box tip" style="margin-top:14px"><b>Главное</b>Вместо «сколько исходов» — «какой размер». Нарисуй картинку и закрась хорошую часть.</div>`};

/* ---------- generators ---------- */
const gens=[];
const G=(lvl,make,star,rule)=>gens.push({lvl,make,star,rule});

/* L0 idea */
G(0,()=>{const r=ch('отношение длины (площади) хорошей части к длине (площади) всей фигуры',['число хороших точек, делённое на число всех точек','длина хорошей части, умноженная на длину всей фигуры','всегда 1/2, потому что точка либо попала, либо нет']);
return {type:'choice',q:'Точку выбирают случайно и равномерно в фигуре. Чему равна <b>геометрическая вероятность</b> попасть в её часть?',...r,
short:'P = мера хорошей части : мера всего.',
explain:'Точек бесконечно много — посчитать их штуками нельзя. Поэтому сравнивают <b>размеры</b>: P = длина (площадь, время) хорошей части <b>:</b> длина (площадь, время) всей фигуры.<br>«1/2, потому что либо да, либо нет» — ловушка: исходы «попал» и «не попал» не равновозможны.',
explain2:'Залей фигуру дождём. Сколько капель упадёт на кусок? Столько, какую долю площади он занимает. Если кусок — треть фигуры, то и шанс — треть.'};},false,true);
G(0,()=>{const r=ch('0',['1','1/2','нельзя сказать']);
return {type:'choice',q:'Точку случайно выбирают на отрезке [0; 10]. Какова вероятность, что она попадёт <b>ровно</b> в точку 7?',...r,
short:'У точки нет длины — вероятность 0.',
explain:'Длина одной точки равна 0. P = 0 : 10 = <b>0</b>.<br>Поэтому для геометрической вероятности неважно, включаем ли концы отрезков: P(x ≤ 7) = P(x < 7).',
explain2:'Попробуй угадать число на отрезке [0; 10] «с бесконечной точностью»: 7,000000…? Шанс угадать все бесконечные цифры — ноль. Но ноль ≠ невозможно: какая-то точка всё-таки выпадет.'};},false,true);
G(0,()=>{const L=pick([5,6,8,10,12,15,20]);const a=R(1,L-1);const right=Math.random()<0.5;const good=right?L-a:a;
return {type:'num',q:`Точку случайно выбирают на отрезке [0; ${L}]. Какова вероятность, что она окажется ${right?'правее':'левее'} числа ${a}?`,pic:segSVG(0,L,[right?[a,L]:[0,a]]),...FA(good,L),
short:`${good} : ${L} = ${FT(good,L)}.`,
explain:`Шаг 1: длина всего отрезка ${L}.<br>Шаг 2: хорошие точки — от ${right?a:0} до ${right?L:a}, длина ${good}.<br>Шаг 3: P = ${F(good,L)} = <b>${FH(good,L)}</b>.`,
explain2:`Раздели отрезок на ${L} равных кусочков по 1. ${right?'Правее':'Левее'} ${a} лежит ${good} из них. Доля: ${FH(good,L)}.`};});
G(0,()=>{const a=pick([4,5,6,8,10]);let b;do{b=R(1,a-1);}while(false);
return {type:'num',q:`Внутри квадрата со стороной ${a} нарисован квадрат со стороной ${b}. Точку случайно бросают в большой квадрат. Какова вероятность попасть в маленький?`,pic:plane(a,a,g=>`${rectOut(g,a,a)}<rect x="${g.X((a-b)/2)}" y="${g.Y((a+b)/2)}" width="${b*g.S}" height="${b*g.S}" ${HL} stroke="var(--accent-ink)"/><text x="${g.X(a/2)}" y="${g.Y(0)+16}" text-anchor="middle" font-size="12" fill="var(--ink)">${a}</text><text x="${g.X(a/2)}" y="${g.Y((a-b)/2)+14}" text-anchor="middle" font-size="12" fill="var(--ink)">${b}</text>`,{size:150,pad:22}),...FA(b*b,a*a),
short:`${b}² : ${a}² = ${FT(b*b,a*a)}.`,
explain:`Мера здесь — <b>площадь</b>.<br>Шаг 1: S большого = ${a}² = ${a*a}.<br>Шаг 2: S маленького = ${b}² = ${b*b}.<br>Шаг 3: P = ${F(b*b,a*a)} = <b>${FH(b*b,a*a)}</b>.${FT(b,a)!==FT(b*b,a*a)?`<br>${FH(b,a)} — ловушка: это отношение сторон, а не площадей.`:''}`,
explain2:`Нарисуй сетку ${a} × ${a} из единичных клеток — всего ${a*a} клеток. Маленький квадрат накрывает ${b*b} клеток. Доля ${FH(b*b,a*a)}.`};});
G(0,()=>{const T=pick([6,8,10,12,15,20]);const t=R(1,T-1);const more=Math.random()<0.5;const good=more?T-t:t;
return {type:'num',q:`Автобус ходит строго каждые ${T} минут. Ты приходишь на остановку в случайный момент. Какова вероятность ждать <b>${more?'больше':'не больше'}</b> ${t} ${plural(t,'минуты','минут','минут')}?`,...FA(good,T),
short:`${good} : ${T} = ${FT(good,T)}.`,
explain:`Между автобусами — отрезок времени ${T} мин. Момент прихода — случайная точка на нём.<br>${more?`Ждать больше ${t} мин — значит прийти в первые ${T-t} мин после ушедшего автобуса.`:`Ждать не больше ${t} мин — значит прийти в последние ${t} мин перед автобусом.`}<br>P = ${F(good,T)} = <b>${FH(good,T)}</b>.`,
explain2:`Проверка через противоположное: P(ждать ≤ ${t}) = ${FH(t,T)}, P(ждать > ${t}) = ${FH(T-t,T)}. В сумме 1 ✅.`};});

/* L1 segment */
G(1,()=>{const r=ch('P = |CD| / |AB|',['P = |AB| / |CD|','P = |CD| · |AB|','P = 1 / |CD|']);
return {type:'choice',q:'На отрезке AB лежит отрезок CD. Точку случайно выбирают на AB. По какой формуле найти вероятность, что она попадёт на CD?',opts:r.opts.map(M),ans:r.ans,
short:'Длина хорошей части : длина всего.',
explain:'Хорошая часть — CD, вся фигура — AB. <b>P = |CD| / |AB|</b>. Вероятность не может быть больше 1, поэтому меньшая длина — в числителе.',
explain2:'AB = 10, CD = 2: шанс попасть на CD — 2 из 10. Если бы делили наоборот, получилось бы 5 — вероятности больше 1 не бывает!'};},false,true);
G(1,()=>{let a,b,c,d;do{a=R(-6,2);b=a+R(6,14);c=R(a,b-2);d=R(c+1,b);}while(d-c===b-a);const L=b-a,l=d-c;
return {type:'num',q:`Число x случайно выбирают на отрезке [${N(a)}; ${N(b)}]. Какова вероятность, что ${N(c)} ≤ x ≤ ${N(d)}?`,pic:segSVG(a,b,[[c,d]]),...FA(l,L),
short:`${l} : ${L} = ${FT(l,L)}.`,
explain:`Шаг 1: длина всего отрезка: ${N(b)} − ${a<0?`(${N(a)})`:N(a)} = ${L}.<br>Шаг 2: длина хорошей части: ${N(d)} − ${c<0?`(${N(c)})`:N(c)} = ${l}.<br>Шаг 3: P = ${F(l,L)} = <b>${FH(l,L)}</b>.`,
explain2:`Частая ошибка — делить на ${N(b)} (правый конец). Длина — это всегда «правый конец минус левый». Отрезок [${N(a)}; ${N(b)}] содержит ${L} единичных кусочков, хорошая часть — ${l}.`};});
G(1,()=>{let a,b,k;do{a=-R(1,6);b=R(2,8);k=R(1,5);}while(k*k>=Math.max(a*a,b*b)||(k>=-a&&k>=b));
const lo=Math.max(a,-k),hi=Math.min(b,k);const l=hi-lo,L=b-a;ok(l>0&&l<L,'sq');
return {type:'num',q:`Число x случайно выбирают на отрезке [${N(a)}; ${N(b)}]. Какова вероятность, что x² < ${k*k}?`,...FA(l,L),
hint:`Сначала реши неравенство x² < ${k*k}.`,
short:`−${k} < x < ${k}; внутри [${N(a)}; ${N(b)}] это (${N(lo)}; ${N(hi)}), P = ${FT(l,L)}.`,
explain:`Шаг 1: x² < ${k*k} ⇔ −${k} < x < ${k}.<br>Шаг 2: пересекаем с отрезком [${N(a)}; ${N(b)}]: получаем (${N(lo)}; ${N(hi)}), длина ${l}.<br>Шаг 3: длина всего отрезка ${L}. P = ${F(l,L)} = <b>${FH(l,L)}</b>.<div class="fig">${segSVG(a,b,[[lo,hi]])}</div>`,
explain2:`Проверь точками: x = ${N(hi-0.5)}: квадрат ${N((hi-0.5)**2)} < ${k*k} ✅. x = ${N(b)}: ${b*b} ${b*b<k*k?'<':'≥'} ${k*k}${b*b<k*k?' ✅':' ❌'}. Хорошие точки — только от ${N(lo)} до ${N(hi)}.`};});
G(1,()=>{const L=pick([10,12,20,30,50,100]);let d;do{d=R(1,Math.floor(L/2)-1);}while(L-2*d<=0);const good=L-2*d;
return {type:'num',q:`Палку длиной ${L} см ломают в случайной точке. Какова вероятность, что <b>оба</b> куска окажутся длиннее ${d} см?`,...FA(good,L),
hint:'Пусть x — расстояние от левого конца до места излома. Какие условия на x?',
short:`${d} < x < ${L-d}: длина ${good}, P = ${FT(good,L)}.`,
explain:`Шаг 1: куски x и ${L} − x.<br>Шаг 2: x > ${d} и ${L} − x > ${d} ⇔ ${d} < x < ${L-d}.<br>Шаг 3: хорошая длина ${L-d} − ${d} = ${good}. P = ${F(good,L)} = <b>${FH(good,L)}</b>.<div class="fig">${segSVG(0,L,[[d,L-d]])}</div>`,
explain2:`Плохие места излома — у краёв: первые ${d} см и последние ${d} см, вместе ${2*d} см. P(плохо) = ${FH(2*d,L)}, P(хорошо) = 1 − ${FH(2*d,L)} = ${FH(good,L)}.`};});
G(1,()=>{const k=R(2,6);let c=0,n=20000;for(let i=0;i<n;i++){const x=(i+0.5)/n;const s=Math.min(x,1-x),l=Math.max(x,1-x);if(l>=k*s)c++;}ok(near(c/n,2/(k+1),0.001),'kpiece');
return {type:'num',q:`Палку ломают в случайной точке. Какова вероятность, что больший кусок окажется <b>хотя бы в ${k} раза</b> длиннее меньшего?`,...FA(2,k+1),
hint:'Пусть длина палки 1, а излом в точке x < 1/2 (меньший кусок слева). Когда 1 − x ≥ k·x?',
short:`Излом ближе ${F(1,k+1)} к любому концу: P = ${FT(2,k+1)}.`,
explain:`Пусть палка [0; 1], меньший кусок x (излом в левой половине).<br>Шаг 1: условие 1 − x ≥ ${k}x ⇔ x ≤ ${F(1,k+1)}.<br>Шаг 2: для излома в правой половине — симметрично: в последней ${F(1,k+1)}.<br>Шаг 3: хорошая длина ${F(1,k+1)} + ${F(1,k+1)} = ${FH(2,k+1)}. P = <b>${FH(2,k+1)}</b>.<div class="fig">${segSVG(0,k+1,[[0,1],[k,k+1]],{})}</div><div class="small">(палка нарисована длиной ${k+1} — так концы целые)</div>`,
explain2:`Возьми палку длиной ${k+1} см. Больший кусок в ${k} раз длиннее меньшего ровно при изломе в 1 см от конца (1 и ${k}). Ближе к концу — ещё «неравнее». Хорошие места: по 1 см у каждого конца, 2 см из ${k+1}. P = ${FH(2,k+1)}.`};});

/* L2 figure */
G(2,()=>{const r=ch('площадь хорошей части : площадь всей фигуры',['периметр хорошей части : периметр фигуры','площадь фигуры : площадь хорошей части','число углов хорошей части : число углов фигуры']);
return {type:'choice',q:'Точку случайно бросают в фигуру. Как найти вероятность, что она попадёт в закрашенную часть?',...r,
short:'P = S(хорошей части) : S(фигуры).',
explain:'Для фигуры на плоскости «размер» — это <b>площадь</b>. P = S(закрашенной) : S(всей).<br>Периметр не годится: длинная тонкая полоса имеет большой периметр, но в неё почти невозможно попасть.',
explain2:'Капли дождя распределяются по площади: на вдвое большую площадь падает вдвое больше капель.'};},false,true);
G(2,()=>{const n=pick([4,5,6]);const k=R(2,n*n-2);const cells=sample(range(0,n*n-1),k).map(c=>[c%n,Math.floor(c/n)]);
return {type:'num',q:`Точку случайно бросают в квадрат ${n} × ${n} клеток. Какова вероятность, что она попадёт в закрашенную клетку?`,pic:cellsSVG(n,cells),...FA(k,n*n),
short:`${k} клет${plural(k,'ка','ки','ок')} из ${n*n}: ${FT(k,n*n)}.`,
explain:`Площадь измеряем в клетках.<br>Шаг 1: всего ${n} · ${n} = ${n*n} клеток.<br>Шаг 2: закрашено ${k}.<br>Шаг 3: P = ${F(k,n*n)} = <b>${FH(k,n*n)}</b>.`,
explain2:`Пересчитай закрашенные клетки по строкам. Каждая клетка — 1/${n*n} площади. ${k} клеток — ${FH(k,n*n)}.`};});
G(2,()=>{const v=pick([['круг, вписанный в квадрат','π/4',Math.PI/4,['1/4','π/2','4/π']],['квадрат, вписанный в круг (точку бросают в круг)','2/π',2/Math.PI,['1/2','π/4','1/π']]]);
const r=ch(v[1],v[3]);
const sq=v[1]==='π/4';
return {type:'choice',q:sq?'В квадрат вписан круг. Точку случайно бросают в квадрат. Какова вероятность, что она попадёт в круг?':'В круг вписан квадрат. Точку случайно бросают в круг. Какова вероятность, что она попадёт в квадрат?',pic:sq?circInSq():plane(2,2,g=>`<circle cx="${g.X(1)}" cy="${g.Y(1)}" r="${g.S}" fill="var(--card)" stroke="var(--fig)" stroke-width="2"/><polygon points="${g.P([[1,0],[2,1],[1,2],[0,1]])}" ${HL} stroke="var(--accent-ink)"/><line x1="${g.X(1)}" y1="${g.Y(1)}" x2="${g.X(2)}" y2="${g.Y(1)}" stroke="var(--fig)" stroke-dasharray="3 2"/><text x="${g.X(1.5)}" y="${g.Y(1)-5}" font-size="13" text-anchor="middle" fill="var(--ink)">r</text>`,{size:150,pad:20}),opts:r.opts.map(M),ans:r.ans,
short:sq?'πr² : (2r)² = π/4 ≈ 0,79.':'2r² : πr² = 2/π ≈ 0,64.',
explain:sq?`Пусть радиус r. Сторона квадрата 2r, его площадь 4r². Площадь круга πr².<br>P = ${F('πr²','4r²')} = <b>π/4</b> ≈ 0,785.<br>1/4 — ловушка: π не исчезает, исчезает только r.`:`Пусть радиус r. Диагонали квадрата — два диаметра (2r), площадь квадрата = ½ · d₁ · d₂ = ½ · 2r · 2r = 2r². Площадь круга πr².<br>P = ${F('2r²','πr²')} = <b>2/π</b> ≈ 0,64.`,
explain2:sq?'Возьми r = 1: квадрат 2 × 2 площадью 4, круг площадью π ≈ 3,14. 3,14 : 4 ≈ 0,79 — круг занимает почти 80 % квадрата, что видно и на рисунке.':'Возьми r = 1: круг площадью π ≈ 3,14, квадрат — 2. 2 : 3,14 ≈ 0,64.'};});
G(2,()=>{const a=pick([2,3,4,5,6]);let r;do{r=R(1,a);}while(false);const v=Math.PI*r*r/4/(a*a);
return {type:'num',q:`Точку случайно бросают в квадрат ABCD со стороной ${a}. Какова вероятность, что расстояние от неё до вершины A меньше ${r}? Ответ округли до сотых (π ≈ 3,14).`,pic:plane(a,a,g=>`${rectOut(g,a,a)}<path d="M${g.X(0)},${g.Y(0)} L${g.X(r)},${g.Y(0)} A${r*g.S},${r*g.S} 0 0 0 ${g.X(0)},${g.Y(r)} Z" ${HL} stroke="var(--accent-ink)"/><text x="${g.X(0)-6}" y="${g.Y(0)+14}" font-size="13" font-weight="700" fill="var(--ink)" text-anchor="end">A</text><text x="${g.X(a/2)}" y="${g.Y(0)+16}" font-size="12" text-anchor="middle" fill="var(--ink)">${a}</text>`,{size:150,pad:24}),...RA(v),
hint:`Точки ближе ${r} к A — это круг радиуса ${r}. Какая его часть внутри квадрата?`,
short:`¼ · π · ${r}² : ${a}² = ${F(`${r*r===1?'':r*r}π`,4*a*a)} ≈ ${N(r2(v))}.`,
explain:`Шаг 1: точки ближе ${r} к A — круг радиуса ${r} с центром A.<br>Шаг 2: внутри квадрата — только <b>четверть</b> круга (угол квадрата 90°): площадь ¼ · π · ${r*r} = ${F(`${r*r===1?'':r*r}π`,4)}.<br>Шаг 3: площадь квадрата ${a*a}. P = ${F(`${r*r===1?'':r*r}π`,4*a*a)} ≈ <b>${N(r2(v))}</b>.`,
explain2:`Численно: четверть круга ≈ 0,785 · ${r*r} = ${N(Math.round(0.785398*r*r*1000)/1000)}; делим на ${a*a}: ≈ ${N(r2(v))}.`};});
G(2,()=>{const k=pick([2,3,4]);const r=ch(FH(1,k*k),[FH(1,k),FH(1,k*k*2),FH(2,k*k)]);
return {type:'choice',q:`В треугольнике провели ${k===2?'средние линии':`прямые, параллельные сторонам, разделив каждую сторону на ${k} равные части`}. Получилась сетка из маленьких треугольников. Точку бросают в большой треугольник. Какова вероятность попасть в один отмеченный <b>маленький треугольник</b>?`,pic:plane(k,k*0.87,g=>{let s='';const P=(i,j)=>[i+j/2,j*0.87];for(let j=0;j<k;j++)for(let i=0;i<k-j;i++){const t=[P(i,j),P(i+1,j),P(i,j+1)];s+=`<polygon points="${g.P(t)}" fill="${i===0&&j===0?'var(--hl)':'var(--card)'}" ${i===0&&j===0?'fill-opacity="0.6"':''} stroke="var(--fig)"/>`;if(i<k-j-1){const u=[P(i+1,j),P(i+1,j+1),P(i,j+1)];s+=`<polygon points="${g.P(u)}" fill="var(--card)" stroke="var(--fig)"/>`;}}return s;},{size:170,pad:12}),opts:r.opts.map(M),ans:r.ans,
short:`Маленьких треугольников ${k*k}, все равны: P = ${FT(1,k*k)}.`,
explain:`Шаг 1: стороны маленького треугольника в ${k} раза меньше сторон большого.<br>Шаг 2: значит, его площадь в ${k}² = ${k*k} раз меньше (подобные фигуры).<br>Шаг 3: P = <b>${FH(1,k*k)}</b>.<br>${FH(1,k)} — ловушка: так относятся стороны, а не площади.`,
explain2:`Посчитай маленькие треугольники на рисунке: в рядах ${range(1,k).map(i=>2*i-1).join(' + ')} = ${k*k}. Они одинаковые, так что каждый — ${FH(1,k*k)} площади.`};});

/* L3 target */
G(3,()=>{const k=R(2,5);const r=ch(`в ${k*k} раз`,[`в ${k} раз`,`в ${2*k} раз`,`в ${k*k*k} раз`]);
return {type:'choice',q:`Радиус одного круга в ${k} раза больше радиуса другого. Во сколько раз больше его площадь?`,...r,
short:`S = πr²: радиус ×${k} → площадь ×${k*k}.`,
explain:`Площадь круга <b>S = πr²</b>. Если радиус увеличить в ${k} раза: π(${k}r)² = ${k*k}πr². Площадь больше <b>в ${k*k} раз</b>.<br>Поэтому в мишенях считаем <b>квадраты</b> радиусов.`,
explain2:`Пицца диаметром 30 см не вдвое, а вчетверо больше пиццы диаметром 15 см. Проверь: (30/15)² = 4.`};},false,true);
G(3,()=>{const R0=pick([3,4,5,6,8,10]);const r=R(1,R0-1);
return {type:'num',q:`Мишень — круг радиуса ${R0} см, «яблочко» — круг радиуса ${r} см в центре. Дротик случайно попадает в мишень. Какова вероятность попасть в яблочко?`,pic:targetSVG([r,R0],0),...FA(r*r,R0*R0),
short:`${r}² : ${R0}² = ${FT(r*r,R0*R0)}.`,
explain:`Шаг 1: площадь яблочка π · ${r}² = ${r*r}π.<br>Шаг 2: площадь мишени π · ${R0}² = ${R0*R0}π.<br>Шаг 3: P = ${F(r*r+'π',R0*R0+'π')} = <b>${FH(r*r,R0*R0)}</b>. π сокращается.${FT(r,R0)!==FT(r*r,R0*R0)?`<br>${FH(r,R0)} — ловушка: отношение радиусов, а не площадей.`:''}`,
explain2:`Площадь растёт как квадрат радиуса: (${r}/${R0})² = ${FH(r*r,R0*R0)}.`};});
G(3,()=>{const n=R(3,5);const rs=range(1,n);const i=R(1,n-1);const good=rs[i]**2-rs[i-1]**2,all=n*n;
return {type:'num',q:`Мишень состоит из кругов с радиусами ${rs.join(', ')} (см). Какова вероятность при случайном попадании в мишень попасть в <b>выделенное кольцо</b> (между радиусами ${rs[i-1]} и ${rs[i]})?`,pic:targetSVG(rs,i),...FA(good,all),
short:`(${rs[i]}² − ${rs[i-1]}²) : ${n}² = ${good}/${all}${FT(good,all)!==good+'/'+all?' = '+FT(good,all):''}.`,
explain:`Шаг 1: площадь кольца = круг радиуса ${rs[i]} минус круг радиуса ${rs[i-1]}: ${rs[i]**2}π − ${rs[i-1]**2}π = ${good}π.<br>Шаг 2: площадь всей мишени ${all}π.<br>Шаг 3: P = ${F(good,all)} = <b>${FH(good,all)}</b>.`,
explain2:`Ширина у всех колец одинаковая (1 см), но площади разные: ${rs.map((r,j)=>j===0?1:r*r-rs[j-1]**2).join(', ')} (в «π-единицах»). Чем дальше от центра, тем кольцо «жирнее». Наше — ${good} из ${all}.`};});
G(3,()=>{const R0=pick([6,8,10,12]);let r1,r2;do{r1=R(1,R0-2);r2=R(r1+1,R0);}while(r2===R0&&r1<2);const good=R0*R0-(r2*r2-r1*r1);
return {type:'num',q:`Мишень радиуса ${R0}. Красным покрашено кольцо от радиуса ${r1} до радиуса ${r2}. Какова вероятность случайно <b>не</b> попасть в красное кольцо?`,...FA(good,R0*R0),
hint:'Сначала найди вероятность попасть в кольцо.',
short:`1 − (${r2}² − ${r1}²)/${R0}² = ${FT(good,R0*R0)}.`,
explain:`Шаг 1: P(в кольцо) = (${r2*r2} − ${r1*r1}) : ${R0*R0} = ${FH(r2*r2-r1*r1,R0*R0)}.<br>Шаг 2: «не попасть» — противоположное событие: P = 1 − ${FH(r2*r2-r1*r1,R0*R0)} = <b>${FH(good,R0*R0)}</b>.`,
explain2:`Напрямую: «не в кольце» = центральный круг радиуса ${r1} (${r1*r1}π) + внешняя часть от ${r2} до ${R0} (${R0*R0-r2*r2}π). Сумма ${good}π из ${R0*R0}π.`};});

/* L4 time */
G(4,()=>{const r=ch('t / T',['T / t','(T − t) / T','t / (T + t)']);
return {type:'choice',q:'Автобус ходит каждые T минут, ты приходишь в случайный момент. Какова вероятность ждать <b>не больше t</b> минут (t < T)?',opts:r.opts.map(M),ans:r.ans,
short:'Хорошее время t из цикла T.',
explain:'Ждать не больше t — значит прийти в последние t минут перед автобусом. Это кусок длиной t из цикла длиной T: <b>P = t/T</b>.<br>(T − t)/T — это вероятность ждать <b>больше</b> t.',
explain2:'T = 10, t = 10: ты точно дождёшься за 10 минут → P = 10/10 = 1 ✅. t = 0: шанс прийти прямо к автобусу 0 ✅. Формула t/T работает.'};},false,true);
G(4,()=>{const g=R(3,9)*5,y=R(1,2)*3,r=R(3,9)*5;const T=g+y+r;const what=pick([['зелёный',g],['красный',r],['жёлтый',y]]);
return {type:'num',q:`Светофор работает по циклу: зелёный ${g} с, жёлтый ${y} с, красный ${r} с. Машина подъезжает в случайный момент. Какова вероятность попасть на <b>${what[0]}</b>?`,...FA(what[1],T),
short:`${what[1]} : ${T} = ${FT(what[1],T)}.`,
explain:`Шаг 1: полный цикл ${g} + ${y} + ${r} = ${T} с.<br>Шаг 2: ${what[0]} горит ${what[1]} с.<br>Шаг 3: P = ${F(what[1],T)} = <b>${FH(what[1],T)}</b>.`,
explain2:`Нарисуй отрезок времени длиной ${T}: кусок ${g} (зел.), ${y} (жёлт.), ${r} (красн.). Момент — случайная точка. Доля ${what[0]}ого куска: ${FH(what[1],T)}.`};});
G(4,()=>{const T=pick([3,4,5,6,8,10]);const t=R(1,T-1);
return {type:'num',q:`Поезд метро приходит каждые ${T} мин. Какова вероятность, что тебе придётся ждать <b>больше ${t}</b> мин?`,...FA(T-t,T),
short:`(${T} − ${t}) : ${T} = ${FT(T-t,T)}.`,
explain:`Ждать больше ${t} мин — если ты пришёл в первые ${T-t} мин после ушедшего поезда.<br>P = ${F(T-t,T)} = <b>${FH(T-t,T)}</b>.`,
explain2:`Противоположное: ждать не больше ${t} — P = ${FH(t,T)}. Тогда P(больше) = 1 − ${FH(t,T)} = ${FH(T-t,T)}.`};});
G(4,()=>{const T=45;const a=R(2,12),b=R(2,12);const good=a+b;
return {type:'num',q:`Урок длится ${T} минут. Уведомление на телефон приходит в случайный момент урока. Какова вероятность, что оно придёт в первые ${a} мин <b>или</b> в последние ${b} мин?`,...FA(good,T),
short:`(${a} + ${b}) : ${T} = ${FT(good,T)}.`,
explain:`Хорошие куски: [0; ${a}] и [${T-b}; ${T}]. Они не пересекаются, общая длина ${a} + ${b} = ${good}.<br>P = ${F(good,T)} = <b>${FH(good,T)}</b>.`,
explain2:`«Или» для непересекающихся кусков — складываем длины, как в правиле сложения. ${good} мин из ${T}.`,pic:segSVG(0,T,[[0,a],[T-b,T]])};});
G(4,()=>{const T=60;const k=pick([2,3,4,5,6]);const per=T/k;const w=R(1,per-1);
const good=w*k;
return {type:'num',q:`Курьер подъезжает к шлагбауму в случайный момент. Шлагбаум открывается ${k} ${plural(k,'раз','раза','раз')} в час через равные промежутки (каждые ${per} мин). Курьер готов ждать не больше ${w} мин. Какова вероятность, что он дождётся?`,...FA(w,per),
hint:`Весь час не нужен — достаточно одного промежутка между открытиями.`,
short:`${w} : ${per} = ${FT(w,per)}.`,
explain:`Час делится на ${k} одинаковых промежутков по ${per} мин. В каждом из них хорошие — последние ${w} мин.<br>За весь час: ${k} · ${w} = ${good} мин из 60, P = ${F(good,60)} = <b>${FH(w,per)}</b>.<br>Или сразу: ${w} из ${per}.`,
explain2:`Все промежутки одинаковые, поэтому внутри одного вероятность та же, что и за час: ${FH(w,per)}.`};});

/* L5 meeting */
G(5,()=>{const r=ch('|x − y| ≤ t',['x + y ≤ t','x ≤ t и y ≤ t','x · y ≤ t']);
return {type:'choice',q:'Двое приходят в случайные моменты x и y (в минутах) и ждут друг друга t минут. При каком условии они встретятся?',opts:r.opts.map(M),ans:r.ans,
short:'Встреча ⇔ разница моментов не больше t.',
explain:'Кто пришёл раньше, ждёт t минут. Значит, второй должен прийти не позже чем через t: <b>|x − y| ≤ t</b>. На квадрате это полоса вдоль диагонали.<br>«x ≤ t и y ≤ t» — оба пришли в начале, но двое, пришедшие в 12:50 и 12:55, тоже встретятся!',
explain2:'Ты пришёл в 12:10, друг в 12:20, ждёте по 15 минут. |10 − 20| = 10 ≤ 15 — встретились. Если друг в 12:30: |10 − 30| = 20 > 15 — ты уже ушёл.'};},false,true);
G(5,()=>{const opts=[['полоса вдоль диагонали',sqSVG(1,[meetPoly(1,0.3,0.3)],{size:110,tl:'T'})],['треугольник под диагональю',sqSVG(1,[[[0,0],[1,0],[1,1]]],{size:110,tl:'T'})],['левый нижний квадратик',sqSVG(1,[[[0,0],[0.3,0],[0.3,0.3],[0,0.3]]],{size:110,tl:'T'})],['два угловых треугольника',sqSVG(1,[[[0.3,0],[1,0],[1,0.7]],[[0,0.3],[0,1],[0.7,1]]],{size:110,tl:'T'})]];
const o=shuffle(opts.map((x,i)=>({x,i})));
return {type:'choice',pics:true,q:'По оси x — время прихода Артёма, по оси y — время прихода Паши (от 0 до T). Каждый ждёт другого t минут. Какая закрашенная область — это «<b>они встретились</b>»?',opts:o.map(z=>z.x[1]),ans:o.findIndex(z=>z.i===0),
short:'|x − y| ≤ t — полоса вдоль диагонали.',
explain:'Встреча ⇔ |x − y| ≤ t ⇔ x − t ≤ y ≤ x + t. Это всё, что лежит между прямыми y = x − t и y = x + t, — <b>полоса вдоль диагонали</b>.<br>Два угловых треугольника — наоборот, «не встретились».',
explain2:'Диагональ y = x — это «пришли одновременно» (точно встретились). Чуть выше и чуть ниже диагонали — пришли почти одновременно, тоже встретились. Далеко от диагонали — разница большая, не встретились.'};});
G(5,()=>{const T=60;const t=pick([5,10,12,15,20,24,30,36,40,45]);const n=(T*T)-(T-t)**2,d=T*T;ok(near(gridP((x,y)=>Math.abs(x-y)<=t,T,T),n/d,0.01),'meet');
return {type:'num',q:`Артём и Паша договорились встретиться у входа в кинотеатр между 18:00 и 19:00. Каждый приходит в случайный момент этого часа и ждёт другого ${t} минут, потом уходит. Какова вероятность встречи?`,pic:sqSVG(T,[meetPoly(T,t,t)],{tl:'60',xl:'Артём',yl:'Паша',diag:true}),...FA(n,d),
hint:`Найди площадь двух угловых треугольников (там встречи нет): катеты 60 − ${t}.`,
short:`1 − (${T-t}/60)² = ${FT(n,d)}.`,
explain:`Шаг 1: все исходы — квадрат 60 × 60, площадь 3 600.<br>Шаг 2: нет встречи — два треугольника с катетами 60 − ${t} = ${T-t}. Вместе это квадрат ${T-t} × ${T-t} = ${(T-t)**2}.<br>Шаг 3: площадь полосы 3 600 − ${(T-t)**2} = ${n}.<br>Шаг 4: P = ${F(n,3600)} = <b>${FH(n,d)}</b>.`,
explain2:`Через доли: катет треугольника — ${FH(T-t,T)} стороны. Два треугольника вместе — квадрат площадью (${FH(T-t,T)})² = ${FH((T-t)**2,T*T)} от всего. P = 1 − ${FH((T-t)**2,T*T)} = ${FH(n,d)}.`};});
G(5,()=>{const T=60;let a,b;do{a=pick([10,15,20,30,40]);b=pick([5,10,15,20,30]);}while(a===b);
const n=2*T*T-(T-a)**2-(T-b)**2,d=2*T*T;ok(near(gridP((x,y)=>(y>=x?y-x<=a:x-y<=b),T,T),n/d,0.01),'asym');
return {type:'num',q:`Аня и Боря встречаются между 12:00 и 13:00, каждый приходит в случайный момент. Аня готова ждать Борю ${a} минут, а Боря Аню — только ${b}. Какова вероятность встречи?`,pic:sqSVG(T,[meetPoly(T,a,b)],{tl:'60',xl:'Аня',yl:'Боря',diag:true}),...FA(n,d),
hint:'Треугольники «без встречи» теперь разные: в одном катет 60 − (время ожидания Ани), в другом — 60 − (Бори).',
short:`1 − (${T-a}² + ${T-b}²)/(2 · 3600) = ${FT(n,d)}.`,
explain:`x — время Ани, y — Бори.<br>Шаг 1: если Аня раньше (x < y), встреча при y − x ≤ ${a}. Иначе — при x − y ≤ ${b}.<br>Шаг 2: без встречи — треугольник с катетами ${T-a} (площадь ½ · ${(T-a)**2} = ${(T-a)**2/2}) и с катетами ${T-b} (площадь ${(T-b)**2/2}).<br>Шаг 3: P = 1 − ${F(`${(T-a)**2/2} + ${(T-b)**2/2}`,'3 600')} = <b>${FH(n,d)}</b>.`,
explain2:`Проверка: если бы оба ждали ${a}, было бы ${FH(T*T-(T-a)**2,T*T)}; оба по ${b} — ${FH(T*T-(T-b)**2,T*T)}. Наш ответ ${FH(n,d)} ≈ ${N(r2(n/d))} — ровно посередине (среднее этих двух). Логично!`};});
G(5,()=>{const T=24;const a=pick([1,2,3]);let b=pick([1,2,3,4]);const n=2*T*T-(T-a)**2-(T-b)**2,d=2*T*T;ok(near(gridP((x,y)=>(y>=x?y-x<a:x-y<b),T,T),n/d,0.01),'ships');
return {type:'num',q:`В течение суток (24 ч) к причалу в случайные моменты подходят два корабля. Первый стоит у причала ${a} ч, второй — ${b} ч. Причал один. Какова вероятность, что одному из кораблей придётся ждать? Ответ округли до сотых.`,...RA(n/d),
hint:'Ждать придётся, если второй корабль подошёл, пока первый ещё стоит. Нарисуй квадрат 24 × 24.',
short:`1 − (${T-a}² + ${T-b}²)/(2 · 24²) = ${FT(n,d)} ≈ ${N(r2(n/d))}.`,
explain:`x — приход первого, y — второго.<br>Шаг 1: если первый раньше (x < y), ждать придётся при y − x < ${a} (первый ещё стоит). Если второй раньше — при x − y < ${b}.<br>Шаг 2: «никто не ждёт» — два треугольника с катетами ${T-a} и ${T-b}: площади ${(T-a)**2/2} и ${(T-b)**2/2}.<br>Шаг 3: P = 1 − ${F(`${(T-a)**2/2} + ${(T-b)**2/2}`,576)} = ${FH(n,d)} ≈ <b>${N(r2(n/d))}</b>.`,
explain2:`Это та же задача о встрече: «корабли встретились у причала» = «одному пришлось ждать». Первый «ждёт» ${a} ч, второй ${b} ч.`};},false);

/* L6 two numbers */
G(6,()=>{const r=ch('случайной точкой (x; y) в квадрате 1 × 1',['случайной точкой на отрезке [0; 2]','случайной точкой на окружности','случайным целым числом от 0 до 1']);
return {type:'choice',q:'Два случайных числа x и y выбирают независимо и равномерно из [0; 1]. Чем удобно изобразить такую пару?',...r,
short:'Пара чисел = точка в единичном квадрате.',
explain:'Пара (x; y) — это <b>координаты точки</b> в квадрате 1 × 1. Площадь квадрата 1, поэтому вероятность события равна площади части квадрата, где оно выполняется.',
explain2:'Как в задаче о встрече: время Ани по оси x, время Бори по оси y. Только здесь «час» — это отрезок [0; 1].'};},false,true);
G(6,()=>{const s=pick([[1,2],[1,3],[2,3],[1,4],[3,4],[1,1],[5,4],[3,2],[4,3],[5,3],[7,4]]);const S=s[0]/s[1];let n,d;
if(S<=1){n=s[0]*s[0];d=2*s[1]*s[1];}else{const t=2*s[1]-s[0];n=2*s[1]*s[1]-t*t;d=2*s[1]*s[1];}
ok(near(gridP((x,y)=>x+y<S,1,1),n/d,0.01),'sum');const less=Math.random()<0.7;const [nn,dd]=less?[n,d]:[d-n,d];
return {type:'num',q:`Числа x и y случайно выбирают из отрезка [0; 1]. Какова вероятность, что x + y ${less?'<':'>'} ${FH(s[0],s[1])}?`,pic:sqSVG(1,[less?sumPoly(S):(S<=1?[[S,0],[1,0],[1,1],[0,1],[0,S]]:[[1,S-1],[1,1],[S-1,1]])],{tl:'1'}),...FA(nn,dd),
hint:`Нарисуй прямую x + y = ${FH(s[0],s[1])} и закрась нужную часть квадрата.`,
short:S<=1?`Треугольник с катетами ${FH(s[0],s[1])}: ${FT(n,d)}${less?'':`; P = 1 − ${FT(n,d)} = ${FT(nn,dd)}`}.`:`1 − ½ · (${FH(2*s[1]-s[0],s[1])})² = ${FT(n,d)}${less?'':`; P = ${FT(nn,dd)}`}.`,
explain:S<=1?`Шаг 1: прямая x + y = ${FH(s[0],s[1])} отсекает от квадрата угол — прямоугольный треугольник с катетами ${FH(s[0],s[1])}.<br>Шаг 2: (0; 0) даёт 0 < ${FH(s[0],s[1])}, значит «x + y < ${FH(s[0],s[1])}» — это треугольник. Его площадь ½ · (${FH(s[0],s[1])})² = ${FH(n,d)}.<br>Шаг 3: ${less?`P = <b>${FH(n,d)}</b>.`:`нам нужно «>», это остальная часть квадрата: P = 1 − ${FH(n,d)} = <b>${FH(nn,dd)}</b>.`}`:`Шаг 1: ${FH(s[0],s[1])} > 1, поэтому прямая x + y = ${FH(s[0],s[1])} отрезает от квадрата <b>верхний правый</b> угол.<br>Шаг 2: этот угол (x + y > ${FH(s[0],s[1])}) — треугольник с катетами 2 − ${FH(s[0],s[1])} = ${FH(2*s[1]-s[0],s[1])}, площадь ½ · (${FH(2*s[1]-s[0],s[1])})² = ${FH(d-n,d)}.<br>Шаг 3: ${less?`P(x + y < ${FH(s[0],s[1])}) = 1 − ${FH(d-n,d)} = <b>${FH(n,d)}</b>.`:`P = <b>${FH(nn,dd)}</b>.`}`,
explain2:`Проверь «здравым смыслом»: среднее значение x + y равно 1. ${S<1?`Сумма меньше ${FH(s[0],s[1])} — редкое событие, вероятность меньше ½.`:S>1?`Сумма меньше ${FH(s[0],s[1])} — частое событие, вероятность больше ½.`:'Сумма меньше 1 — ровно половина случаев.'} ${less?'Наш ответ':'P(<)'} = ${FH(n,d)} ✅.`};});
G(6,()=>{const k=pick([2,3,4,5]);const inv=Math.random()<0.5;/* y > kx  or y > x/k */
let n,d;if(!inv){n=1;d=2*k;}else{n=2*k-1;d=2*k;}ok(near(gridP((x,y)=>inv?y>x/k:y>k*x,1,1),n/d,0.01),'ykx');
return {type:'num',q:`Числа x и y случайно выбирают из [0; 1]. Какова вероятность, что ${inv?`y > ${F('x',k)}`:`y > ${k}x`}?`,pic:sqSVG(1,[inv?[[0,0],[1,1/k],[1,1],[0,1]]:[[0,0],[1/k,1],[0,1]]],{tl:'1'}),...FA(n,d),
short:inv?`Под прямой y = x/${k} треугольник площадью ${FT(1,2*k)}; P = 1 − ${FT(1,2*k)} = ${FT(n,d)}.`:`Над прямой y = ${k}x треугольник с катетами 1 и ${FT(1,k)}: ${FT(n,d)}.`,
explain:inv?`Шаг 1: прямая y = x/${k} идёт из (0; 0) в (1; ${FH(1,k)}).<br>Шаг 2: под ней — треугольник с катетами 1 и ${FH(1,k)}, площадь ½ · 1 · ${FH(1,k)} = ${FH(1,2*k)}.<br>Шаг 3: нам нужно «выше»: P = 1 − ${FH(1,2*k)} = <b>${FH(n,d)}</b>.`:`Шаг 1: прямая y = ${k}x идёт из (0; 0) и выходит на верхнюю сторону в точке (${FH(1,k)}; 1).<br>Шаг 2: над ней — треугольник с вершинами (0; 0), (0; 1), (${FH(1,k)}; 1). Катеты 1 и ${FH(1,k)}.<br>Шаг 3: площадь ½ · 1 · ${FH(1,k)} = <b>${FH(n,d)}</b>.`,
explain2:`Проверь точкой: (0; 1) — y = 1 > ${inv?`0/${k}`:`${k}·0`} = 0, подходит, значит закрашенная часть содержит левый верхний угол ✅.`};});
G(6,()=>{const dd=pick([[1,2],[1,3],[2,3],[1,4],[3,4],[1,5],[2,5],[3,5],[1,10],[3,10]]);const D=dd[0]/dd[1];const t=dd[1]-dd[0];const n=dd[1]*dd[1]-t*t,d=dd[1]*dd[1];ok(near(gridP((x,y)=>Math.abs(x-y)<D,1,1),n/d,0.01),'absdiff');
return {type:'num',q:`Компьютер выбирает два случайных числа из [0; 1]. Какова вероятность, что они отличаются <b>меньше чем на ${FH(dd[0],dd[1])}</b>?`,pic:sqSVG(1,[meetPoly(1,D,D)],{tl:'1',diag:true}),...FA(n,d),
short:`1 − (1 − ${FT(dd[0],dd[1])})² = ${FT(n,d)}.`,
explain:`Шаг 1: условие |x − y| < ${FH(dd[0],dd[1])} — полоса вдоль диагонали (как в задаче о встрече).<br>Шаг 2: вне полосы — два треугольника с катетами 1 − ${FH(dd[0],dd[1])} = ${FH(t,dd[1])}; вместе это квадрат площадью (${FH(t,dd[1])})² = ${FH(t*t,d)}.<br>Шаг 3: P = 1 − ${FH(t*t,d)} = <b>${FH(n,d)}</b>.`,
explain2:`Это задача о встрече с T = 1 и временем ожидания ${FH(dd[0],dd[1])}. Формула та же: 1 − ((T − t)/T)².`};});
G(6,()=>{const a=pick([[1,2],[1,3],[2,3],[1,4],[3,4],[2,5],[3,5],[1,5],[3,10],[7,10]]);const b=pick([[1,2],[1,3],[2,3],[1,4],[3,4],[2,5],[4,5]]);
const n=(a[1]-a[0])*(b[1]-b[0]),d=a[1]*b[1];
return {type:'num',q:`Числа x и y случайно выбирают из [0; 1]. Какова вероятность, что x > ${FH(a[0],a[1])} <b>и</b> y > ${FH(b[0],b[1])}?`,pic:sqSVG(1,[[[a[0]/a[1],b[0]/b[1]],[1,b[0]/b[1]],[1,1],[a[0]/a[1],1]]],{tl:'1'}),...FA(n,d),
short:`(1 − ${FT(a[0],a[1])}) · (1 − ${FT(b[0],b[1])}) = ${FT(n,d)}.`,
explain:`Хорошая часть — прямоугольник в правом верхнем углу.<br>Шаг 1: его ширина 1 − ${FH(a[0],a[1])} = ${FH(a[1]-a[0],a[1])}.<br>Шаг 2: высота 1 − ${FH(b[0],b[1])} = ${FH(b[1]-b[0],b[1])}.<br>Шаг 3: площадь = ${FH(a[1]-a[0],a[1])} · ${FH(b[1]-b[0],b[1])} = <b>${FH(n,d)}</b>.`,
explain2:`Числа выбираются независимо, поэтому вероятности можно перемножить: P(x > ${FH(a[0],a[1])}) = ${FH(a[1]-a[0],a[1])}, P(y > ${FH(b[0],b[1])}) = ${FH(b[1]-b[0],b[1])}. Произведение ${FH(n,d)} — то же, что площадь прямоугольника.`};});

/* L7 ★ stick, coin */
G(7,()=>{const r=ch('каждый из трёх кусков меньше половины палки',['каждый кусок больше трети палки','хотя бы один кусок меньше половины','два куска равны']);
return {type:'choice',q:'Палку ломают на три куска. Когда из этих кусков можно сложить треугольник?',...r,
short:'Неравенство треугольника ⇔ каждый кусок < ½.',
explain:'По неравенству треугольника самая длинная сторона должна быть меньше суммы двух других. Если кусок a, то остальные вместе 1 − a. a < 1 − a ⇔ <b>a < ½</b>. Это должно выполняться для каждого куска.<br>«Каждый больше трети» — слишком строго: куски 0,2; 0,4; 0,4 образуют треугольник.',
explain2:'Куски 0,6; 0,2; 0,2: две короткие вместе 0,4 — не дотянутся до концов длинной (0,6). Треугольника нет. А 0,4; 0,35; 0,25 — все меньше ½, треугольник есть.'};},true,true);
G(7,()=>{let n=0,c=0;for(let i=0;i<240;i++)for(let j=0;j<240;j++){const x=(i+0.5)/240,y=(j+0.5)/240;const a=Math.min(x,y),b=Math.max(x,y);n++;if(a<0.5&&b-a<0.5&&1-b<0.5)c++;}ok(near(c/n,0.25,0.005),'stick');
const L=pick([1,10,20,30,60,100]);
return {type:'num',q:`Палку длиной ${L===1?'1 м':L+' см'} ломают в двух случайных местах (места выбираются независимо и равномерно). Какова вероятность, что из трёх получившихся кусков можно сложить треугольник?`,...FA(1,4),
hint:'Точки излома (x; y) — точка в квадрате. Условие: каждый кусок меньше половины.',
short:'Два треугольника по 1/8 в квадрате: 1/4.',
explain:`Пусть длина 1 (ответ не зависит от длины), изломы в x и y.<br>Шаг 1: (x; y) — точка в квадрате 1 × 1. Возьмём x < y: куски x, y − x, 1 − y.<br>Шаг 2: каждый < ½: x < ½, y > ½, y − x < ½. Это треугольник (0; ½), (½; ½), (½; 1) площадью ⅛.<br>Шаг 3: при y < x — симметричный треугольник, ещё ⅛.<br>Ответ: ⅛ + ⅛ = <b>1/4</b>.<div class="fig">${sqSVG(1,[[[0,0.5],[0.5,0.5],[0.5,1]],[[0.5,0],[0.5,0.5],[1,0.5]]],{tl:'1',diag:true})}</div>`,
explain2:'Проверь моделированием в теории (виджет «Сломай палку»): после 1000 бросков доля «треугольников» будет около 25 %. Длина палки неважна: условие «каждый кусок меньше половины» масштабируется.'};},true);
G(7,()=>{const a=pick([5,6,8,10,12,15,20]);let d;do{d=R(1,a-1);}while(false);const t=a-d;const cross=Math.random()<0.5;const n=cross?a*a-t*t:t*t,dd=a*a;
return {type:'num',q:`Пол выложен квадратной плиткой со стороной ${a} см. На пол случайно бросают монету диаметром ${d} см. Какова вероятность, что монета ${cross?'<b>заденет</b> хотя бы один шов':'ляжет <b>целиком</b> на одну плитку'}?`,pic:plane(a,a,g=>`${rectOut(g,a,a)}<rect x="${g.X(d/2)}" y="${g.Y(a-d/2)}" width="${t*g.S}" height="${t*g.S}" ${HL} stroke="var(--accent-ink)" stroke-dasharray="4 3"/><circle cx="${g.X(d/2)}" cy="${g.Y(d/2)}" r="${d/2*g.S}" fill="none" stroke="var(--bad)" stroke-width="1.5"/><text x="${g.X(a/2)}" y="${g.Y(0)+16}" font-size="12" text-anchor="middle" fill="var(--ink)">${a}</text>`,{size:150,pad:22}),...FA(n,dd),
hint:'Следи за центром монеты. Где он должен быть, чтобы монета не задела шов?',
short:`Центр в квадрате ${a} − ${d} = ${t}: ${cross?`1 − ${t}²/${a}²`:`${t}²/${a}²`} = ${FT(n,dd)}.`,
explain:`Шаг 1: положение монеты определяется её <b>центром</b>. Центр падает в какую-то плитку — равномерно по её площади (${a}² = ${a*a}).<br>Шаг 2: монета не задевает шов, если центр дальше радиуса (${N(d/2)} см) от каждой стороны. Это квадрат со стороной ${a} − ${d} = ${t} (пунктир), площадь ${t*t}.<br>Шаг 3: P(целиком на плитке) = ${F(t*t,a*a)}${cross?`; P(заденет) = 1 − ${FH(t*t,a*a)} = <b>${FH(n,dd)}</b>`:` = <b>${FH(n,dd)}</b>`}.`,
explain2:`Частая ошибка — вычитать только радиус: ${a} − ${N(d/2)}. Но отступить надо от <b>обеих</b> сторон плитки — получается ${a} − 2 · ${N(d/2)} = ${t}.`};},true);
G(7,()=>{const a=pick([4,5,6,8,10]);const d=R(1,a-1);const n=a-d;
return {type:'num',q:`Пол из длинных досок шириной ${a} см. Монету диаметром ${d} см бросают на пол. Какова вероятность, что монета <b>не заденет</b> щель между досками?`,...FA(n,a),
short:`Центр в полосе шириной ${a} − ${d} = ${n}: ${FT(n,a)}.`,
explain:`Доски длинные — важно только расстояние от центра монеты до щелей поперёк доски.<br>Шаг 1: центр падает в полосу шириной ${a} равномерно.<br>Шаг 2: не задевает, если центр дальше ${N(d/2)} от обеих щелей: полоса шириной ${a} − ${d} = ${n}.<br>Шаг 3: P = ${F(n,a)} = <b>${FH(n,a)}</b>.`,
explain2:`Это одномерная версия «монеты на плитке»: вместо квадрата — отрезок. Поэтому без квадрата: ${n}/${a}, а не (${n}/${a})².`};},true);

/* L8 ★ olympiad */
G(8,()=>{const r=ch('p² − 4q ≥ 0',['p² + 4q ≥ 0','p − 4q ≥ 0','p² ≥ q']);
return {type:'choice',q:'Когда у уравнения <span class="m">x² + px + q = 0</span> есть действительные корни?',opts:r.opts.map(M),ans:r.ans,
short:'Дискриминант D = p² − 4q ≥ 0.',
explain:'Корни есть, если дискриминант неотрицателен: D = p² − 4·1·q = <b>p² − 4q ≥ 0</b>, то есть q ≤ p²/4.<br>Это пригодится в задаче, где p и q выбираются случайно: хорошая область — под параболой q = p²/4.',
explain2:'x² + 2x + 1 = 0: D = 4 − 4 = 0 — один корень −1 ✅. x² + 1 = 0: D = −4 < 0 — корней нет ✅.'};},true,true);
G(8,()=>{const a=pick([1,2]);const n=a*a,d=12;ok(near(gridP((p,q)=>p*p>=4*q,a,1,300),n/d,0.01),'quad');
return {type:'num',q:`Числа p и q выбирают случайно: p из отрезка [0; ${a}], q из [0; 1]. Какова вероятность, что уравнение <span class="m">x² + px + q = 0</span> имеет действительные корни?`,pic:plane(a,1,g=>{let pts=[];for(let i=0;i<=40;i++){const p=i/40*a;pts.push([p,Math.min(1,p*p/4)]);}pts.push([a,0]);return `<polygon points="${g.P(pts)}" ${HL} stroke="var(--accent-ink)"/>${rectOut(g,a,1)}<text x="${g.X(a)}" y="${g.Y(0)+16}" font-size="12" text-anchor="middle" fill="var(--ink)">${a}</text><text x="${g.X(a/2)}" y="${g.Y(0)+16}" font-size="13" font-style="italic" fill="var(--accent-ink)" text-anchor="middle">p</text><text x="${g.X(0)-8}" y="${g.Y(0.5)}" font-size="13" font-style="italic" fill="var(--accent-ink)" text-anchor="end">q</text><text x="${g.X(0)-6}" y="${g.Y(1)+4}" font-size="12" fill="var(--ink)" text-anchor="end">1</text>`;},{size:200,pad:26}),...FA(n,d),
hint:'Корни есть ⇔ q ≤ p²/4. Найди площадь под параболой: площадь под y = x² от 0 до a равна a³/3.',
short:`Площадь под q = p²/4 на [0; ${a}]: ${FT(a**3,12)}; делим на ${a}: ${FT(n,d)}.`,
explain:`Шаг 1: все исходы — прямоугольник ${a} × 1, площадь ${a}.<br>Шаг 2: корни есть ⇔ q ≤ ${F('p²',4)} — область под параболой (она не выходит за q = 1 при p ≤ 2).<br>Шаг 3: площадь под y = x² на [0; a] равна a³/3 (это факт из анализа, его можно принять). Под p²/4: ${F(`${a}³`,'3 · 4')} = ${FH(a**3,12)}.<br>Шаг 4: P = ${FH(a**3,12)} : ${a} = <b>${FH(n,d)}</b>.`,
explain2:`Проверка «моделированием»: я разбил прямоугольник на 90 000 маленьких клеток и посчитал, в скольких p² ≥ 4q. Доля ≈ ${N(r2(n/d))} — совпадает с ${FH(n,d)}.`};},true);
G(8,()=>{const v=Math.PI/8;ok(near(gridP((x,y)=>(x-0.5)**2+y*y<0.25,1,1,300),v,0.005),'obtuse');
const r=ch('π/8',['1/2','π/4','1/8']);
return {type:'choice',q:'Точку P случайно бросают в квадрат ABCD со стороной 1. Какова вероятность, что угол APB — <b>тупой</b>?',pic:plane(1,1,g=>`${rectOut(g,1,1)}<path d="M${g.X(0)},${g.Y(0)} A${g.S/2},${g.S/2} 0 0 0 ${g.X(1)},${g.Y(0)} Z" ${HL} stroke="var(--accent-ink)"/><text x="${g.X(0)-6}" y="${g.Y(0)+14}" font-size="13" font-weight="700" text-anchor="end" fill="var(--ink)">A</text><text x="${g.X(1)+6}" y="${g.Y(0)+14}" font-size="13" font-weight="700" fill="var(--ink)">B</text><text x="${g.X(1)+6}" y="${g.Y(1)+4}" font-size="13" font-weight="700" fill="var(--ink)">C</text><text x="${g.X(0)-6}" y="${g.Y(1)+4}" font-size="13" font-weight="700" text-anchor="end" fill="var(--ink)">D</text>`,{size:150,pad:24}),opts:r.opts.map(M),ans:r.ans,
hint:'Где лежат точки, из которых отрезок AB виден под прямым углом?',
short:'Внутри полукруга на AB: (π · ¼ / 2) : 1 = π/8.',
explain:'Шаг 1: из точек окружности с диаметром AB отрезок виден под прямым углом (вписанный угол, опирающийся на диаметр). Внутри круга угол <b>тупой</b>, снаружи — острый.<br>Шаг 2: внутри квадрата лежит половина этого круга: радиус ½, площадь ½ · π · (½)² = π/8.<br>Шаг 3: площадь квадрата 1. P = <b>π/8</b> ≈ 0,39.',
explain2:'Проверь: центр квадрата (½; ½) лежит ровно на окружности (расстояние до середины AB равно ½) — угол APB там прямой. Точка чуть ниже — внутри полукруга, угол тупой. Численная проверка сеткой даёт ≈ 0,393 = π/8.'};},true);
G(8,()=>{let A=pick([[1,2],[1,3],[2,3]]);const a=A[0]/A[1];/* point on segment [0,1] then P(longer >= ? ) - use: two points on segment, distance < a  */
const n=A[1]*A[1]-(A[1]-A[0])**2,d=A[1]*A[1];ok(near(gridP((x,y)=>Math.abs(x-y)<a,1,1),n/d,0.01),'two pts');
return {type:'num',q:`На отрезке длиной 1 случайно и независимо отмечают две точки. Какова вероятность, что расстояние между ними будет <b>больше ${FH(A[0],A[1])}</b>?`,...FA(d-n,d),
hint:'Это задача о встрече «наоборот».',
short:`(1 − ${FT(A[0],A[1])})² = ${FT(d-n,d)}.`,
explain:`Шаг 1: точки x и y — пара чисел из [0; 1], то есть точка в квадрате.<br>Шаг 2: |x − y| > ${FH(A[0],A[1])} — два угловых треугольника с катетами 1 − ${FH(A[0],A[1])} = ${FH(A[1]-A[0],A[1])}.<br>Шаг 3: вместе они дают квадрат площадью (${FH(A[1]-A[0],A[1])})² = <b>${FH(d-n,d)}</b>.`,
explain2:`Это дополнение к задаче о встрече: P(встреча) = 1 − ${FH(d-n,d)} = ${FH(n,d)}, значит P(далеко) = ${FH(d-n,d)}.`};},true);

/* ---------- widgets ---------- */
function onTheory(root){
 const w=root.querySelector('#w-dart');
 if(w){w.innerHTML=`<b>Бросай точки в квадрат — и найди π</b><div style="display:flex;gap:8px;flex-wrap:wrap;margin:6px 0"><button class="btn ghost" id="d1">+10 точек</button><button class="btn ghost" id="d2">+500 точек</button><button class="btn ghost" id="d0">Сброс</button></div><div id="dpic" class="fig"></div><div id="dout" style="line-height:1.7"></div>`;
  let pts=[];const draw=()=>{const S=200;let s=SV(S+20,S+20,'Бросание точек')+`<rect x="10" y="10" width="${S}" height="${S}" fill="var(--card)" stroke="var(--fig)" stroke-width="2"/><circle cx="${10+S/2}" cy="${10+S/2}" r="${S/2}" fill="var(--hl)" fill-opacity="0.25" stroke="var(--accent-ink)" stroke-width="1.5"/>`;
   const show=pts.slice(-1500);show.forEach(([x,y,h])=>{s+=`<circle cx="${(10+x*S).toFixed(1)}" cy="${(10+y*S).toFixed(1)}" r="1.8" fill="${h?'var(--accent-ink)':'var(--bad)'}"/>`;});
   w.querySelector('#dpic').innerHTML=s+'</svg>';const n=pts.length,h=pts.filter(p=>p[2]).length;
   w.querySelector('#dout').innerHTML=n?`Брошено: <b>${n}</b>, в круге: <b>${h}</b>. Доля: ${N(Math.round(h/n*1000)/1000)} (теория: π/4 ≈ 0,785)<br>Оценка π ≈ 4 · ${h}/${n} = <b>${N(Math.round(4*h/n*1000)/1000)}</b>`:'Нажми кнопку — точки полетят случайно. Синие попали в круг, красные — нет.';};
  const add=k=>{for(let i=0;i<k;i++){const x=Math.random(),y=Math.random();pts.push([x,y,(x-0.5)**2+(y-0.5)**2<0.25]);}draw();};
  w.querySelector('#d1').onclick=()=>add(10);w.querySelector('#d2').onclick=()=>add(500);w.querySelector('#d0').onclick=()=>{pts=[];draw();};draw();}
 const m=root.querySelector('#w-meet');
 if(m){m.innerHTML=`<b>Задача о встрече: сколько ждать?</b><label>Ждём t = <input type="range" id="mt" min="0" max="60" value="15"><output id="mto"></output></label><div id="mpic" class="fig"></div><div id="mout" style="line-height:1.7"></div>`;
  const u=()=>{const t=+m.querySelector('#mt').value;m.querySelector('#mto').textContent=t+' мин';m.querySelector('#mpic').innerHTML=sqSVG(60,t>0?[meetPoly(60,t,t)]:[],{tl:'60',xl:'ты',yl:'друг',diag:true});
   const n=3600-(60-t)**2;m.querySelector('#mout').innerHTML=`Нет встречи: два треугольника, вместе ${60-t} × ${60-t} = ${(60-t)**2}<br>P = 1 − ${F((60-t)**2,3600)} = <b>${FH(n,3600)}</b> ≈ ${N(r2(n/3600))} (наивно «t/60» дало бы ${N(r2(t/60))})`;};
  m.querySelector('#mt').oninput=u;u();}
 const k=root.querySelector('#w-stick');
 if(k){k.innerHTML=`<b>Сломай палку!</b><div style="display:flex;gap:8px;flex-wrap:wrap;margin:6px 0"><button class="btn ghost" id="s1">Сломать 1 палку</button><button class="btn ghost" id="s2">Сломать 1000</button><button class="btn ghost" id="s0">Сброс</button></div><div id="spic" class="fig"></div><div id="sout" style="line-height:1.7"></div>`;
  let n=0,c=0,last=null;const one=()=>{const x=Math.random(),y=Math.random();const a=Math.min(x,y),b=Math.max(x,y);const p=[a,b-a,1-b];const t=p.every(v=>v<0.5);n++;if(t)c++;return {a,b,p,t};};
  const draw=()=>{k.querySelector('#spic').innerHTML=last?stickSVG(1,[last.a,last.b],{lab:last.p.map(v=>N(Math.round(v*100)/100))}):'';
   k.querySelector('#sout').innerHTML=(last?`Куски: ${last.p.map(v=>N(Math.round(v*100)/100)).join('; ')} → ${last.t?'<b>треугольник есть</b> ✅ (все меньше 0,5)':'<b>треугольника нет</b> ❌ (есть кусок ≥ 0,5)'}<br>`:'Нажми кнопку, чтобы сломать палку в двух случайных местах.<br>')+(n?`Сломано палок: <b>${n}</b>, треугольников: <b>${c}</b>, доля: <b>${N(Math.round(c/n*1000)/1000)}</b> (теория: 0,25)`:'');};
  k.querySelector('#s1').onclick=()=>{last=one();draw();};k.querySelector('#s2').onclick=()=>{for(let i=0;i<999;i++)one();last=one();draw();};k.querySelector('#s0').onclick=()=>{n=0;c=0;last=null;draw();};draw();}
}

window.TOPIC={id:'s9_geom_prob',title:'Геометрическая вероятность',subtitle:'Вероятность и статистика · 9 класс',
intro:`<p>Когда исходов бесконечно много, вероятность считают через длины, площади и время. Точка на отрезке, точка в фигуре, мишень, автобус и светофор, знаменитая задача о встрече. В конце — олимпиадные задачи: сломанная палка, монета на плитке, случайное квадратное уравнение.</p>`,
theory,symbols,figs:{},onTheory,
levels:['Идея геометрической вероятности','Точка на отрезке','Точка в фигуре','Мишень и дартс','Случайный момент времени','Задача о встрече','Два случайных числа','★ Палка и монета','★ Олимпиадные задачи'],
gens};
})();
